const settingsFields = {
  defaultIssueStatus: z.enum([
    "backlog",
    "todo",
    "in_progress",
    "in_review",
    "done",
    "canceled",
  ]),
  allowPublicProjects: z.boolean(),
  requireTwoFactor: z.boolean(),
  digestHourUtc: z.number().int().min(0).max(23),
  enabledFlagOverrides: z.array(z.string()),
};

/** The full settings block: every key has a default, for a new organization. */
export const organizationSettingsSchema = z.object({
  defaultIssueStatus: settingsFields.defaultIssueStatus.default("backlog"),
  allowPublicProjects: settingsFields.allowPublicProjects.default(false),
  requireTwoFactor: settingsFields.requireTwoFactor.default(false),
  digestHourUtc: settingsFields.digestHourUtc.default(7),
  enabledFlagOverrides: settingsFields.enabledFlagOverrides.default([]),
});

/**
 * A save patch. Its keys carry no defaults: `.partial()` keeps a `.default()`
 * on each key, so a defaulted key would overwrite the stored value of every
 * key the caller left out.
 */
export const organizationSettingsPatchSchema = z
  .object(settingsFields)
  .partial();

