import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { updateOrganizationSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function seededTenant(slug: string) {
  const tenant = await createTenant(slug, "growth");
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: {
      defaultIssueStatus: "todo",
      allowPublicProjects: false,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email", "activity_feed"],
    },
  });
  return tenant;
}

async function settingsOf(orgId: Parameters<typeof orgRepo.findOrgById>[0]) {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new Error("missing org");
  return org.settings;
}

describe("organization settings saves (scratch)", () => {
  it("schema keeps absent settings keys absent", () => {
    const parsed = updateOrganizationSchema.parse({
      orgId: "org_x",
      settings: { allowPublicProjects: true },
    });
    expect(parsed.settings).toEqual({ allowPublicProjects: true });
  });

  it("a partial save leaves every other stored setting alone", async () => {
    const tenant = await seededTenant("scratch-partial");
    await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { allowPublicProjects: true },
    });
    expect(await settingsOf(tenant.org.id)).toEqual({
      defaultIssueStatus: "todo",
      allowPublicProjects: true,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email", "activity_feed"],
    });
  });

  it("a default-status save does not switch feature overrides off", async () => {
    const tenant = await seededTenant("scratch-status");
    await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { defaultIssueStatus: "done" },
    });
    const settings = await settingsOf(tenant.org.id);
    expect(settings.defaultIssueStatus).toBe("done");
    expect(settings.enabledFlagOverrides).toEqual(["digest_email", "activity_feed"]);
    expect(settings.digestHourUtc).toBe(18);
  });

  it("submitted 0, false and empty list all take effect", async () => {
    const tenant = await seededTenant("scratch-falsy");
    await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: {
        digestHourUtc: 0,
        requireTwoFactor: false,
        enabledFlagOverrides: [],
      },
    });
    const settings = await settingsOf(tenant.org.id);
    expect(settings.digestHourUtc).toBe(0);
    expect(settings.requireTwoFactor).toBe(false);
    expect(settings.enabledFlagOverrides).toEqual([]);
    expect(settings.defaultIssueStatus).toBe("todo");
  });

  it("a rename changes no settings", async () => {
    const tenant = await seededTenant("scratch-rename");
    const before = await settingsOf(tenant.org.id);
    const renamed = await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "Scratch Renamed Inc",
    });
    expect(renamed.name).toBe("Scratch Renamed Inc");
    expect(await settingsOf(tenant.org.id)).toEqual(before);
  });

  it("a save in one workspace never touches another", async () => {
    const a = await seededTenant("scratch-iso-a");
    const b = await seededTenant("scratch-iso-b");
    const bBefore = await settingsOf(b.org.id);
    await orgService.updateOrganization(a.actors.owner, {
      orgId: a.org.id,
      settings: { digestHourUtc: 3, enabledFlagOverrides: [] },
    });
    expect(await settingsOf(b.org.id)).toEqual(bBefore);
  });

  it("an invalid digest hour is still rejected", async () => {
    const tenant = await seededTenant("scratch-invalid");
    await expect(
      orgService.updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        settings: { digestHourUtc: 24 },
      }),
    ).rejects.toThrow();
    expect((await settingsOf(tenant.org.id)).digestHourUtc).toBe(18);
  });
});

